structural.cypher:
USE GRAPH CorpusKG 
INTERPRET OPENCYPHER QUERY () {
MATCH (a:Officeholder)-[:PREDECESSOR]-(p:Name)
WHERE toLower(a.name) CONTAINS "a. n. r. robinson"
RETURN a AS officeholder, p AS predecessor
}

